/// Source templates generated by `crap4dart goldens scaffold` into the
/// target Flutter project (default `test/golden/`).
///
/// The templates live here as strings (not compiled library code)
/// because the generated code depends on `flutter_test`, which a
/// pure-Dart package cannot depend on.
///
/// Design rules baked into the scaffold (see IstiN/crap4dart#32):
/// * app scopes install at `MaterialApp.builder` — ABOVE the
///   Navigator. Wrapping only `MaterialApp.home` loses the scopes on
///   every pushed route (the exact FahThemeScope bug this guards
///   against);
/// * every scene runs phone + desktop × light + dark — the
///   `golden.require_viewport_matrix` matrix;
/// * a scrolled variant per scene seeds enough rows to scroll past
///   glass/translucent headers so the golden shows real content
///   underneath, not a bare translucent color;
/// * goldens are directory-per-scene-file and `update_goldens.sh`
///   regenerates one scene at a time — flutter's `--update-goldens`
///   rewrites every golden a test file touches, so one scene per file
///   keeps unrelated baselines untouched;
/// * fixtures are in-memory and deterministic — no network, no clock,
///   no shared mutable state. Opt into app-specific fake modes (e.g.
///   glass fake) explicitly per scene.
library;

/// The scene harness: app wrapper + golden-variant pump helper.
const String goldenScaffoldHelper = r'''
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

/// One quadrant of the visual-regression matrix: phone/desktop
/// surface × light/dark theme.
enum GoldenVariant {
  phoneLight(Size(390, 844), Brightness.light),
  phoneDark(Size(390, 844), Brightness.dark),
  desktopLight(Size(1280, 800), Brightness.light),
  desktopDark(Size(1280, 800), Brightness.dark);

  const GoldenVariant(this.surfaceSize, this.brightness);

  /// Logical pixel surface the scene is rendered on.
  final Size surfaceSize;

  /// Theme brightness the scene is rendered with.
  final Brightness brightness;

  /// File-name suffix: `settings_<suffix>.png`.
  String get fileSuffix => switch (this) {
        GoldenVariant.phoneLight => 'phone_light',
        GoldenVariant.phoneDark => 'phone_dark',
        GoldenVariant.desktopLight => 'desktop_light',
        GoldenVariant.desktopDark => 'desktop_dark',
      };
}

/// Installs [scopes] ABOVE the Navigator via `MaterialApp.builder`.
///
/// This is the load-bearing rule of the scaffold: scopes wrapped only
/// around `MaterialApp.home` are lost on every pushed route, which
/// renders pushed screens with the default theme (empty glass headers,
/// missing colors). `builder` receives the widget tree above the
/// Navigator, so pushed routes inherit every scope.
class GoldenScaffoldApp extends StatelessWidget {
  const GoldenScaffoldApp({
    super.key,
    required this.child,
    this.scopes = goldenScaffoldDefaultScopes,
    this.theme,
  });

  /// The screen under test.
  final Widget child;

  /// App-wide scopes (theme, providers, feature flags). Defaults to a
  /// plain MaterialApp theme; override with your app's real scopes.
  final Widget Function(BuildContext context, Widget child) scopes;

  /// Base theme; [GoldenVariant.brightness] is applied on top.
  final ThemeData? theme;

  @override
  Widget build(BuildContext context) => MaterialApp(
        debugShowCheckedModeBanner: false,
        theme: theme ?? ThemeData(useMaterial3: true),
        builder: (context, navigatorChild) => scopes(
          context,
          navigatorChild ?? child,
        ),
        home: child,
      );
}

/// The no-op default for [GoldenScaffoldApp.scopes].
Widget goldenScaffoldDefaultScopes(BuildContext context, Widget child) =>
    child;

/// Pumps [scene] through one [variant] of the matrix and compares
/// against `goldens/<sceneName>_<variant>.png`.
///
/// When [scrolled] is true the scene is pumped, then dragged to the
/// bottom before the snapshot — glass/translucent headers then show
/// real rows underneath instead of a bare translucent color.
///
/// [scopes] lets a scene inject app scopes at `MaterialApp.builder`;
/// pass your app's real wrapper here (see [GoldenScaffoldApp]).
Future<void> pumpGoldenScene(
  WidgetTester tester, {
  required String sceneName,
  required GoldenVariant variant,
  required Widget scene,
  bool scrolled = false,
  Widget Function(BuildContext context, Widget child)? scopes,
  ThemeData? theme,
}) async {
  tester.view.physicalSize = variant.surfaceSize;
  tester.view.devicePixelRatio = 1.0;
  addTearDown(tester.view.reset);
  await tester.pumpWidget(GoldenScaffoldApp(
    scopes: scopes ?? goldenScaffoldDefaultScopes,
    theme: (theme ?? ThemeData(useMaterial3: true)).copyWith(
      brightness: variant.brightness,
    ),
    child: scene,
  ));
  await tester.pumpAndSettle();
  if (scrolled) {
    await tester.drag(find.byType(Scrollable).first, const Offset(0, -10000));
    await tester.pumpAndSettle();
  }
  await expectLater(
    find.byType(GoldenScaffoldApp),
    matchesGoldenFile('goldens/${sceneName}_${variant.fileSuffix}.png'),
  );
}
''';

/// The example scene file generated next to the harness.
const String goldenScaffoldExampleScene = r'''
@TestOn('vm')

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import '../golden_scaffold_helper.dart';

void main() {
  // Opt into app-specific fake modes here when your app uses them —
  // glass/translucent surfaces otherwise render real blurs, which are
  // timing-sensitive and make goldens flaky:
  //
  //   setUp(() => debugMyGlassAlwaysFake = true);
  //   tearDown(() => debugMyGlassAlwaysFake = false);
  //
  // Fixtures must be in-memory and deterministic: no network, no
  // clock, no shared mutable state. Seed enough items to scroll so
  // the scrolled variant has real rows under glass headers.

  for (final variant in GoldenVariant.values) {
    testWidgets('example scene — ${variant.fileSuffix}', (tester) async {
      await pumpGoldenScene(
        tester,
        sceneName: 'example',
        variant: variant,
        // TODO: replace with the real screen built from in-memory
        // fixtures (e.g. MemoryStore(), FakeAdapter(), ...).
        scene: const _ExampleScene(),
      );
    });

    testWidgets('example scene scrolled — ${variant.fileSuffix}',
        (tester) async {
      await pumpGoldenScene(
        tester,
        sceneName: 'example_scrolled',
        variant: variant,
        scrolled: true,
        scene: const _ExampleScene(items: 60),
      );
    });
  }
}

class _ExampleScene extends StatelessWidget {
  const _ExampleScene({this.items = 12});

  final int items;

  @override
  Widget build(BuildContext context) => Scaffold(
        appBar: AppBar(title: const Text('Example')),
        body: ListView.builder(
          itemCount: items,
          itemBuilder: (context, i) => ListTile(
            title: Text('Row $i'),
            subtitle: const Text('Concrete visible content'),
          ),
        ),
      );
}
''';

/// The scoped golden-regeneration script.
const String goldenScaffoldUpdateScript = r'''
#!/bin/sh
# Regenerates goldens for ONE scene file — nothing else.
#
# flutter test --update-goldens rewrites every golden the test file
# touches, so the scaffold keeps one scene per file: updating
# scenes/foo_golden_test.dart can never rewrite scenes/bar baselines.
#
# After regenerating, review the montage (montage.html), then rerun
# WITHOUT --update-goldens to confirm the suite is green:
#
#   sh test/golden/update_goldens.sh foo_golden_test.dart
#   open test/golden/montage.html            # pixel review
#   flutter test test/golden/scenes          # green without -u
set -e
root="$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)"
scene="${1:?usage: update_goldens.sh <scene>_golden_test.dart}"
cd "$root"
flutter test "test/golden/scenes/$scene" --update-goldens
dart run test/golden/montage.dart
''';

/// The montage generator: an HTML contact sheet of every golden,
/// grouped by scene, for the pixel-review step.
const String goldenScaffoldMontage = r'''
// Regenerates montage.html — a contact sheet of every golden under
// test/golden/goldens, grouped by scene (file name up to the last
// `_variant` segment), for pixel review after a scoped update.
//
// Run: dart run test/golden/montage.dart
import 'dart:io';

void main() {
  final goldenDir = Directory('test/golden/goldens');
  final out = File('test/golden/montage.html');
  final pngs = goldenDir
      .listSync()
      .whereType<File>()
      .where((f) => f.path.endsWith('.png'))
      .map((f) => f.uri.pathSegments.last)
      .toList()
    ..sort();
  if (pngs.isEmpty) {
    stderr.writeln('no goldens under ${goldenDir.path}');
    exitCode = 1;
    return;
  }
  final scenes = <String, List<String>>{};
  for (final png in pngs) {
    final dot = png.lastIndexOf('.');
    final stem = dot < 0 ? png : png.substring(0, dot);
    final lastUnderscore = stem.lastIndexOf('_');
    final scene = lastUnderscore < 0 ? stem : stem.substring(0, lastUnderscore);
    scenes.putIfAbsent(scene, () => []).add(png);
  }
  final buf = StringBuffer()
    ..writeln('<!doctype html><meta charset="utf-8">')
    ..writeln('<title>golden montage</title>')
    ..writeln('<style>body{font:14px sans-serif;background:#222;color:#eee}')
    ..writeln('section{margin:24px 0}img{width:320px;margin:4px;'
        'border:1px solid #555;vertical-align:top}')
    ..writeln('h2{margin:8px 0 4px}</style>');
  for (final entry in scenes.entries) {
    buf
      ..writeln('<section><h2>${entry.key}</h2>')
      ..writeAll(entry.value.map((p) => '<img src="goldens/$p" title="$p">'))
      ..writeln('</section>');
  }
  out.writeAsStringSync(buf.toString());
  stdout.writeln('wrote ${out.path} '
      '(${scenes.length} scenes, ${pngs.length} goldens)');
}
''';

/// README dropped into the goldens directory: naming + review flow.
const String goldenScaffoldReadme = r'''
Goldens live one directory per scene file. Names follow
`<scene>_<variant>.png` where variant is one of phone_light,
phone_dark, desktop_light, desktop_dark (plus `_scrolled` scene
variants).

Workflow:

1. Change a screen.
2. Regenerate only its scene: `sh test/golden/update_goldens.sh <scene>_golden_test.dart`
3. Review the pixels: open `test/golden/montage.html`.
4. Rerun without `--update-goldens` to confirm green:
   `flutter test test/golden/scenes`.

Never regenerate unrelated baselines: one scene per test file is the
contract that keeps `update_goldens.sh` scoped.
''';
